/***********************************************************
***** CHARGE 1240121 CJIS_CASE_NUMBER 2026CF551A14
***********************************************************/

DECLARE
    v_is_valid PLS_INTEGER := 1;
    v_validation_error VARCHAR2(512) := NULL;
    v_count PLS_INTEGER := 0;
    v_error_message VARCHAR2(512);
    v_docket_id_str VARCHAR2(1024);
    v_inserted_id PLS_INTEGER := 0;

BEGIN
   SAVEPOINT before_record;
   
IF v_is_valid = 1 THEN
SELECT COUNT(*)
INTO v_count
FROM JISJDW.audit_trail 
WHERE activity_date_time > TO_DATE('2026-08-18 00:00','YYYY-MM-DD HH24:MI')
AND cjis_case_number = '2026CF551A14'
AND (activity_user_id NOT IN ('JISJDW', 'SYSTEMA', 'PNX2JIS')
    OR activity_user_id is null
);
       
IF v_count <> 0 THEN
    v_is_valid := 0;
    v_validation_error := 'Human activity found in Audit Trail';
END IF;

IF v_is_valid <> 1 THEN
    JISREM.LOG
(
    p_cleanup_id => '213c69d8-e583-4d15-a75e-0885b9e99929',
    p_charge_id    => '1240121',
    p_step_name  => 'NoHumanActivity',
    p_message    => 'Error: ' || v_validation_error
);

   
   UPDATE
        JISREM.CLEANUP_CASE_QUEUE
    SET
        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = '213c69d8-e583-4d15-a75e-0885b9e99929'
        AND charge_id = 1240121;
   
    RETURN;
END IF;

END IF;

       UPDATE JISREM.CLEANUP_CASE_QUEUE
       SET status = 'VALIDATED',
       message = 'All validations passed'
       WHERE cleanup_id = '213c69d8-e583-4d15-a75e-0885b9e99929'
       AND charge_id = '1240121';

JISREM.LOG
(
    p_cleanup_id => '213c69d8-e583-4d15-a75e-0885b9e99929',
    p_charge_id    => '1240121',
    p_step_name  => 'CLEANUP',
